import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation using a bit array and multiple hash functions.
    The bit array size and number of hash functions are calculated based on the
    expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.bit_array_size = self._get_bit_array_size()
        self.num_hashes = self._get_num_hashes()
        self.bit_array = [0] * self.bit_array_size

    def _get_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _get_num_hashes(self) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int(math.ceil((self.bit_array_size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate hash values for the given item using multiple hash functions."""
        result = []
        for i in range(self.num_hashes):
            digest = hashlib.md5(f"{item}{i}".encode()).hexdigest()
            result.append(int(digest, 16) % self.bit_array_size)
        return result

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        for index in self._hashes(item):
            if self.bit_array[index] == 0:
                return False
        return True

