    A Bloom Filter implementation that uses a bit array to determine if an item 
    is possibly in a set or definitely not in a set, with a configurable size and error rate.

    This design uses a list of boolean values to represent the bit array and 
    employs multiple hash functions for added accuracy.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal bit array size and number of hash functions
        self.size = self._optimal_bit_array_size()
        self.num_hashes = self._num_hash_functions()

        # Initialize bit array
        self.bit_array = [False] * self.size

    def _optimal_bit_array_size(self) -> int:
        """Calculates the optimal size of the bit array."""
        return int(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _num_hash_functions(self) -> int:
        """Calculates the optimal number of hash functions."""
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generates hash values for the given item."""
        hash_values = []
        for i in range(self.num_hashes):
            hash_value = int(hashlib.md5(f"{item}{i}".encode()).hexdigest(), 16) % self.size
