import hashlib
import math

class BloomFilter:
    """
    A BloomFilter class that uses a bit array to probabilistically test
    whether an element is a member of a set. False positives are possible,
    but false negatives are not. This implementation uses an optimal bit array size
    and the number of hash functions calculated based on expected items and the desired
    false positive rate.

    Attributes:
        bit_array (list): A list representing the bits of the bloom filter.
        size (int): The size of the bit array.
        num_hashes (int): The number of hash functions used.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than 0.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.num_hashes = self._optimal_num_hashes(self.size, expected_items)
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self, expected_items: int, false_positive_rate: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil((-expected_items * math.log(false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_num_hashes(self, bit_array_size: int, expected_items: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, round(bit_array_size / expected_items * math.log(2)))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash for an item with a given seed."""
        hash_value = hashlib.md5((item + str(seed)).encode()).hexdigest()
        return int(hash_value, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for i in range(self.num_hashes):
            position = self._hash(item, i)
            self.bit_array[position] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
        for i in range(self.num_hashes):
            position = self._hash(item, i)
            if self.bit_array[position] == 0:
                return False
        return True
